```c
#include <stdio.h>
#include <math.h>

int main(void)
{
    int a, b, c;

    scanf("%d%d%d", &a, &b, &c);
    if (a + b > c && a + c > b && b + c > a) {
        double s = (a + b + c) / 2.0;
