    for (x = 1; x <= n / 5; x++) {
        for (y = 1; y <= (n - 5 * x) / 3; y++) {
            z = n - x - y;
            if (z < 1 || z % 3 != 0) {
                continue;
            }
            if (5 * x + 3 * y + z / 3 == n) {
                printf("%d %d %d\n", x, y, z);
                found = 1;
            }
        }
    }
    if (!found) {
        printf("No solution.\n");
    }
    return 0;
}

