#include <stdio.h>
#define MAXN 105

void shift(int *array, int num, int size);

int main(void)
{
    int i, n, p;
    int array[MAXN];

    scanf("%d%d", &n, &p);
    for (i = 0; i < n; i++)
        scanf("%d", &array[i]);

    shift(array, p, n); /* 向左移 p 位 */

