void shift(int *array, int num, int size)
{
    int i, k, t;

    num %= size;
    for (k = 0; k < num; k++)
    {
        t = array[0];
        for (i = 1; i < size; i++)
            array[i - 1] = array[i];
        array[size - 1] = t;
