#define MAXN 1005

int main(void)
{
    int a[MAXN], b[MAXN];
    int na = 0, nb = 0;
    int x, i, j, same, ok;

    /* 读到 -1 为止，-1 不属于序列 */
    while (scanf("%d", &x) == 1 && x != -1)
        a[na++] = x;
    while (scanf("%d", &x) == 1 && x != -1)
        b[nb++] = x;

    ok = 0;
    if (nb <= na)
    {
        for (i = 0; i + nb <= na && !ok; i++)
        {
            same = 1;
            for (j = 0; j < nb; j++)
                if (a[i + j] != b[j])
                {
                    same = 0;
                    break;
                }
            if (same)
                ok = 1;
        }
    }

    if (ok)
        printf("ListB is the sub sequence of ListA.\n");
    else
        printf("ListB is not the sub sequence of ListA.\n");

    return 0;
}

