#define MAXLEN 110

int isPrime(int n)
{
    int i;

    if (n < 2) {
        return 0;
    }
    for (i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return 0;
        }
    }
    return 1;
}

int getResult(char word[])
{
    int cnt[26] = {0};
    int i, max = 0, min = -1, diff;

    for (i = 0; word[i] != '\0'; i++) {
        cnt[word[i] - 'a']++;
