    int len1 = 0, la = 0, lb = 0;
    int i = 0, k = 0, j;

    scanf("%s", s);
    scanf("%s", a);
    scanf("%s", b);
    while (s[len1] != '\0') {
        len1++;
    }
    while (a[la] != '\0') {
        la++;
    }
    while (b[lb] != '\0') {
        lb++;
    }
    while (i < len1) {
        j = 0;
        if (i + la <= len1) {
            while (j < la && s[i + j] == a[j]) {
                j++;
