#include <stdio.h>

/* 把三个整数按升序整理（通过指针修改调用者的变量） */
static void sort3(int *a, int *b, int *c)
{
    int t;

    if (*a > *b) {
        t = *a;
        *a = *b;
        *b = t;
    }
    if (*b > *c) {
        t = *b;
        *b = *c;
        *c = t;
    }
    if (*a > *b) {
        t = *a;
        *a = *b;
        *b = t;
    }
}

/* -1：不是三角形；0：一般三角形；1：直角；2：等腰；3：等边 */
int judgeTriangle(int a, int b, int c)
{
    sort3(&a, &b, &c);
    if (a <= 0 || a + b <= c) {
        return -1;
    }
    if (a == c) {
        return 3;
    }
    if (a * a + b * b == c * c) {
        return 1;
    }
    if (a == b || b == c) {
        return 2;
    }
    return 0;
}

int main(void)
