#include <stdio.h>

/* 打印 n 的素数分解式。
   参数 p 表示起始试除因子：主程序调用时传 1（此时由本层输出 "n=" 和行末换行），
   递归调用时传刚找到的素因子 d（此后不再重复输出 "n="）。 */
void printFactor(int n, int p)
{
    int d;

    if (n == 1 && p < 2) {
        printf("1=1\n");
        return;
    }
    d = (p < 2) ? 2 : p;
    while ((long long)d * d <= n && n % d != 0) {
        d++;
    }
    if ((long long)d * d > n) {
        d = n;            /* 剩下的 n 本身就是素数 */
    }
    if (p < 2) {
        printf("%d=", n);
    }
    printf("%d", d);
    if (n / d > 1) {
        printf("*");
        printFactor(n / d, d);
    }
    if (p < 2) {
        printf("\n");
    }
}

int main(void)
{
    int a, b, i;

    scanf("%d%d", &a, &b);
    for (i = a; i <= b; i++) {
        printFactor(i, 1);
    }
    return 0;
}

