problems.solution:
#include <stdio.h>
#include <string.h>

#define MAXLEN 32   /* 姓名、编号的最大长度 + 余量 */
#define COURSES 3   /* 三项得分 */

typedef struct {
    char name[MAXLEN];      /* 选手姓名，可含空格 */
    char id[MAXLEN];        /* 选手编号 */
    int score[COURSES];     /* 三项得分 */
    int sum;                /* 总分 */
} PLAYER;

/* 去掉 fgets 读入的换行符 */
static void strip_newline(char *s)
{
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[--len] = '\0';
    }
}

int main(void)
{
    PLAYER p;
    PLAYER *ptr = &p;   /* 输出统一用结构体指针访问 */
    int i, j;

    if (fgets(p.name, MAXLEN, stdin) == NULL) {
        return 0;
    }
    strip_newline(p.name);
    if (fgets(p.id, MAXLEN, stdin) == NULL) {
        return 0;
    }
    strip_newline(p.id);

    p.sum = 0;
    for (i = 0; i < COURSES; i++) {
        scanf("%d", &p.score[i]);
        p.sum += p.score[i];
    }

    /* 三项得分从高到低排序（选择排序） */
    for (i = 0; i < COURSES; i++) {
        for (j = i + 1; j < COURSES; j++) {
            if (p.score[j] > p.score[i]) {
                int t = p.score[i];
                p.score[i] = p.score[j];
                p.score[j] = t;
            }
        }
    }

    printf("Name:%s\n", ptr->name);
    printf("Id:%s\n", ptr->id);
    printf("Score:%d %d %d\n", ptr->score[0], ptr->score[1], ptr->score[2]);
    printf("Sum:%d\n", ptr->sum);
    printf("Average:%.2f\n", ptr->sum / (double)COURSES);
    return 0;
}

