    char name[24];
    int total;
} STUDENT;

/* 返回 1 表示 a 应排在 b 之前：总分降序，总分相同按姓名字典序升序 */
static int before(const STUDENT *a, const STUDENT *b)
{
    if (a->total != b->total) {
        return a->total > b->total;
    }
    return strcmp(a->name, b->name) < 0;
}

int main(void)
{
    STUDENT a[MAXN];
