```c
#include <stdio.h>

#define MAXN 105

typedef struct {
    char id[16];
    int total;      /* 综合成绩 */
    int p1;         /* 笔试成绩 */
    int p2;         /* 项目成绩 */
} STU;

/* 交换两个结构体所指向的内容 */
void Swap(STU *s1, STU *s2)
{
    STU t = *s1;
    *s1 = *s2;
    *s2 = t;
}

/* 若 s1 应排在 s2 之前返回 1，否则返回 0 */
int Comp(STU *s1, STU *s2)
{
    if (s1->total != s2->total) {
        return s1->total > s2->total;
    }
    return s1->p1 > s2->p1;
}

/* 选择排序，排序规则全部交给 Comp/Swap */
void Sort(STU a[], int size)
{
    int i, j;
    for (i = 0; i < size; i++) {
        for (j = i + 1; j < size; j++) {
            if (Comp(&a[j], &a[i])) {
                Swap(&a[i], &a[j]);
            }
        }
    }
}

int main(void)
{
    STU stu[MAXN];
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%s %d %d", stu[i].id, &stu[i].p1, &stu[i].p2);
        stu[i].total = stu[i].p1 + stu[i].p2;
    }

    Sort(stu, n);

    for (i = 0; i < n; i++) {
        printf("%s %d %d %d\n", stu[i].id, stu[i].total, stu[i].p1, stu[i].p2);
