```c
#include <stdio.h>
#include <math.h>

/* 复数类型：数据成员只有 re、im，操作全部写成独立函数，模拟「类」 */
typedef struct {
    double re;
    double im;
} Complex;

Complex c_add(Complex a, Complex b)
{
    Complex r;
    r.re = a.re + b.re;
    r.im = a.im + b.im;
    return r;
}

Complex c_sub(Complex a, Complex b)
{
    Complex r;
    r.re = a.re - b.re;
    r.im = a.im - b.im;
    return r;
}

Complex c_mul(Complex a, Complex b)
{
    Complex r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

double c_abs(Complex z)
{
    return sqrt(z.re * z.re + z.im * z.im);
}

void c_print(Complex z)
{
    printf("(%.2f,%.2f)\n", z.re, z.im);
}

int main(void)
{
    Complex a, b;
    char op;
    int n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf(" %c", &op);
        scanf("%lf %lf", &a.re, &a.im);
        if (op == '|') {
            printf("|z|=%.2f\n", c_abs(a));
            continue;
        }
        scanf("%lf %lf", &b.re, &b.im);
        if (op == '+') {
            c_print(c_add(a, b));
        } else if (op == '-') {
            c_print(c_sub(a, b));
        } else {
            c_print(c_mul(a, b));
        }
    }
    return 0;
}

