```c
#include <stdio.h>

typedef struct {
    int y;
    int m;
    int d;
} Date;

static const char *WEEK[7] = {"SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"};

static int is_leap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

/* 把日期换算成「公元 1 年 1 月 1 日以来的第几天」，相减即天数差 */
static long long date_days(Date t)
{
    static const int mdays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    long long y = t.y - 1;
    long long days = y * 365 + y / 4 - y / 100 + y / 400;
    int m;

    for (m = 1; m < t.m; m++) {
        days += mdays[m];
        if (m == 2 && is_leap(t.y)) {
            days += 1;
        }
    }
    days += t.d;
    return days;
}

/* 0 = 星期日，1 = 星期一，……，6 = 星期六 */
static int weekday(Date t)
{
    return (int)(date_days(t) % 7);
}

/* a 比 b 早返回 -1，相同返回 0，晚返回 1 */
static int date_compare(Date a, Date b)
{
    long long da = date_days(a);
    long long db = date_days(b);
    if (da < db) {
        return -1;
    }
    if (da > db) {
        return 1;
    }
    return 0;
}

int main(void)
{
    Date a, b, early;
    long long diff;

    scanf("%d %d %d", &a.y, &a.m, &a.d);
    scanf("%d %d %d", &b.y, &b.m, &b.d);

    if (date_compare(a, b) <= 0) {
        early = a;
    } else {
        early = b;
    }

    diff = date_days(a) - date_days(b);
    if (diff < 0) {
        diff = -diff;
    }

    printf("Earlier:%04d-%02d-%02d\n", early.y, early.m, early.d);
    printf("Days:%lld\n", diff);
    printf("Weekday:%s\n", WEEK[weekday(early)]);
    return 0;
}

