#include <stdio.h>
#include <math.h>

typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    Point lo;   /* 左下角 */
    Point hi;   /* 右上角 */
} Rect;

static Point make_point(double x, double y)
{
    Point p;
    p.x = x;
    p.y = y;
    return p;
}

/* 点在矩形内（含边界）返回 1 */
static int rect_contains(Rect r, Point p)
{
    return p.x >= r.lo.x && p.x <= r.hi.x &&
           p.y >= r.lo.y && p.y <= r.hi.y;
}

/* 点到矩形的最短距离：点在矩形内为 0，否则取到最近边的欧氏距离 */
