{
    if (sc.math >= sc.english && sc.math >= sc.c) {
        return "Math";
    }
    if (sc.english >= sc.c) {
        return "English";
    }
    return "C";
}

/* 总成绩降序，同分按姓名升序 */
static int before(const STUDENT *a, const STUDENT *b)
{
    if (a->total != b->total) {
        return a->total > b->total;
    }
    return strcmp(a->name, b->name) < 0;
}

