#include <stdio.h>

#define MAXN 1005

/* 枚举：两种流水类型 */
typedef enum {
    DEPOSIT = 0,    /* 存入 */
    SPEND = 1       /* 消费 */
} OP;

typedef struct {
    OP op;
    int amount;
} RECORD;

static char op_char(OP op)
{
    switch (op) {
    case DEPOSIT:
        return 'D';
    case SPEND:
        return 'S';
    default:
        return '?';
    }
}

int main(void)
{
    RECORD rec[MAXN];
    int n, i;
    int balance = 0;
    int failed = 0;
    int deposits = 0;
    int max_spend = 0;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        char c;
        scanf(" %c %d", &c, &rec[i].amount);
        switch (c) {
        case 'D':
            rec[i].op = DEPOSIT;
            break;
        case 'S':
            rec[i].op = SPEND;
            break;
        default:
            rec[i].op = DEPOSIT;
            break;
        }
    }

    for (i = 0; i < n; i++) {
        switch (rec[i].op) {
        case DEPOSIT:
            balance += rec[i].amount;
            deposits += rec[i].amount;
            break;
        case SPEND:
            if (rec[i].amount > balance) {
                failed++;
            } else {
                balance -= rec[i].amount;
                if (rec[i].amount > max_spend) {
                    max_spend = rec[i].amount;
