problems.solution:
#include <stdio.h>

#define CAP 205     /* 队列容量，需大于人数 n */

/* 循环队列：head 指向队头，tail 指向下一个空位，count 记录元素个数 */
typedef struct {
    int data[CAP];
    int head;
    int tail;
    int count;
} Queue;

void queue_init(Queue *q)
{
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

int queue_push(Queue *q, int x)
{
    if (q->count >= CAP) {
        return 0;
    }
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % CAP;   /* 到末尾回头，实现循环复用 */
    q->count++;
    return 1;
}

int queue_pop(Queue *q, int *x)
{
    if (q->count == 0) {
        return 0;
    }
    *x = q->data[q->head];
    q->head = (q->head + 1) % CAP;
    q->count--;
    return 1;
}

int queue_front(const Queue *q, int *x)
{
    if (q->count == 0) {
        return 0;
    }
    *x = q->data[q->head];
    return 1;
}

int queue_empty(const Queue *q)
{
    return q->count == 0;
}

int queue_size(const Queue *q)
{
    return q->count;
}

int main(void)
{
    Queue q;
    int n, m, i, k;
    int x = 0;
    int first = 1;

    scanf("%d %d", &n, &m);
    queue_init(&q);
    for (i = 1; i <= n; i++) {
        queue_push(&q, i);
    }

    printf("Order:");
    while (!queue_empty(&q)) {
        /* 前 m-1 个人从队头取出再放到队尾，第 m 个人出列 */
        for (k = 1; k < m; k++) {
            queue_pop(&q, &x);
            queue_push(&q, x);
        }
        queue_pop(&q, &x);
        if (!first) {
            printf(" ");
        }
        printf("%d", x);
        first = 0;
    }
    printf("\n");
    printf("Last:%d\n", x);
    return 0;
}

