#include <stdio.h>
#include <string.h>

#define MAXS 100    /* 最多管理的学生人数 */
#define MAXL 16     /* 学号、姓名的最大长度 + 余量 */

typedef struct {
    char id[MAXL];
    char name[MAXL];
    int math;
    int eng;
    int comp;
} STUDENT;

/* 学生集合：结构体数组 + 当前人数，一组函数负责增删改查 */
typedef struct {
    STUDENT stu[MAXS];
    int count;
} SYSTEM;

void sys_init(SYSTEM *sys)
{
    sys->count = 0;
}

int sys_find(const SYSTEM *sys, const char *id)
{
    int i;
    for (i = 0; i < sys->count; i++) {
        if (strcmp(sys->stu[i].id, id) == 0) {
            return i;
        }
    }
    return -1;
}

double stu_average(const STUDENT *s)
{
    return (s->math + s->eng + s->comp) / 3.0;
}

int sys_add(SYSTEM *sys, const char *id, const char *name, int a, int b, int c)
{
    STUDENT *s;
    if (sys->count >= MAXS || sys_find(sys, id) >= 0) {
        return 0;
    }
    s = &sys->stu[sys->count];
    strcpy(s->id, id);
    strcpy(s->name, name);
    s->math = a;
    s->eng = b;
    s->comp = c;
    sys->count++;
    return 1;
}

int sys_delete(SYSTEM *sys, const char *id)
{
    int pos = sys_find(sys, id);
    int i;
    if (pos < 0) {
        return 0;
    }
    for (i = pos; i < sys->count - 1; i++) {
        sys->stu[i] = sys->stu[i + 1];
    }
    sys->count--;
    return 1;
}

int sys_update(SYSTEM *sys, const char *id, int a, int b, int c)
{
    int pos = sys_find(sys, id);
    if (pos < 0) {
        return 0;
    }
    sys->stu[pos].math = a;
    sys->stu[pos].eng = b;
    sys->stu[pos].comp = c;
    return 1;
}

void sys_show(const SYSTEM *sys, const char *id)
{
    int pos = sys_find(sys, id);
    const STUDENT *s;
    if (pos < 0) {
        printf("Not exist\n");
        return;
    }
    s = &sys->stu[pos];
    printf("ID:%s\n", s->id);
    printf("Name:%s\n", s->name);
    printf("Average:%.1f\n", stu_average(s));
}

/* 按平均分降序输出全体，同分按学号升序（排序在副本上做，不改动原数组） */
void sys_list(const SYSTEM *sys)
{
    STUDENT tmp[MAXS];
    int n = sys->count;
    int i, j;

    memcpy(tmp, sys->stu, sizeof(STUDENT) * (size_t)n);
    for (i = 1; i < n; i++) {
        STUDENT key = tmp[i];
        j = i - 1;
        while (j >= 0) {
            double ka = stu_average(&key);
            double ja = stu_average(&tmp[j]);
            int put = (ja < ka) || (ja == ka && strcmp(tmp[j].id, key.id) > 0);
            if (!put) {
                break;
            }
            tmp[j + 1] = tmp[j];
            j--;
        }
        tmp[j + 1] = key;
    }
    for (i = 0; i < n; i++) {
        printf("%s %s %.1f\n", tmp[i].id, tmp[i].name, stu_average(&tmp[i]));
    }
}

int main(void)
{
    SYSTEM sys;
    int n, i;

    sys_init(&sys);
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        int cmd;
        scanf("%d", &cmd);
        if (cmd == 1) {
            char id[MAXL], name[MAXL];
            int a, b, c;
            scanf("%s %s %d %d %d", id, name, &a, &b, &c);
            printf("%s\n", sys_add(&sys, id, name, a, b, c) ? "Add success" : "Add failed");
        } else if (cmd == 2) {
            char id[MAXL];
            scanf("%s", id);
            printf("%s\n", sys_delete(&sys, id) ? "Delete success" : "Not exist");
        } else if (cmd == 3) {
            char id[MAXL];
            int a, b, c;
            scanf("%s %d %d %d", id, &a, &b, &c);
            printf("%s\n", sys_update(&sys, id, a, b, c) ? "Update success" : "Not exist");
        } else if (cmd == 4) {
            char id[MAXL];
            scanf("%s", id);
            sys_show(&sys, id);
        } else if (cmd == 5) {
            sys_list(&sys);
        }
    }
    return 0;
}

