```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[20];
    int a;       /* 第一场成绩 */
    int b;       /* 第二场成绩 */
    int total;
} PLAYER;

/* 总分降序 -> 第一场成绩降序 -> 姓名升序 */
static int cmp(const void *p, const void *q)
{
    const PLAYER *x = (const PLAYER *)p;
    const PLAYER *y = (const PLAYER *)q;

    if (x->total != y->total) {
        return y->total - x->total;
    }
    if (x->a != y->a) {
        return y->a - x->a;
    }
    return strcmp(x->name, y->name);
}

int main(void)
{
    PLAYER *arr;
    int n, k, i;

    if (scanf("%d %d", &n, &k) != 2) {
        return 0;
    }
    if (n <= 0) {
        return 0;
    }

    /* 按人数动态申请结构体数组，n 可达 200000 */
    arr = (PLAYER *)malloc((size_t)n * sizeof(PLAYER));
    if (arr == NULL) {
        return 1;
    }

    for (i = 0; i < n; i++) {
        scanf("%s %d %d", arr[i].name, &arr[i].a, &arr[i].b);
        arr[i].total = arr[i].a + arr[i].b;
    }

    qsort(arr, (size_t)n, sizeof(PLAYER), cmp);

    for (i = 0; i < k; i++) {
        printf("%d %s %d %d %d\n", i + 1, arr[i].name,
               arr[i].total, arr[i].a, arr[i].b);
    }

    free(arr);
    return 0;
}

