#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

typedef struct {
    int id;
    int math;
    int eng;
    int total;
} Player;

Player stu[MAXN];

/* 总分降序 -> 数学降序 -> 编号升序 */
int cmp(const void *pa, const void *pb)
{
    const Player *a = (const Player *)pa;
    const Player *b = (const Player *)pb;

    if (a->total != b->total) {
        return a->total > b->total ? -1 : 1;
    }
    if (a->math != b->math) {
        return a->math > b->math ? -1 : 1;
    }
    if (a->id != b->id) {
        return a->id < b->id ? -1 : 1;
    }
    return 0;
}

int main(void)
{
    int n, k, i;

    scanf("%d%d", &n, &k);
    for (i = 0; i < n; i++) {
        scanf("%d%d%d", &stu[i].id, &stu[i].math, &stu[i].eng);
        stu[i].total = stu[i].math + stu[i].eng;
    }

    qsort(stu, (size_t)n, sizeof(Player), cmp);

    for (i = 0; i < k; i++) {
        printf("%d %d\n", stu[i].id, stu[i].total);
    }
    return 0;
}

