#include <stdio.h>

static const int mdays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

static int isLeap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

/* 从 1900-01-01 起算，返回该日期是第几天（0 开始） */
static long long serial(int y, int m, int d)
{
    long long s = 0;
    int i;

    for (i = 1900; i < y; i++) {
        s += isLeap(i) ? 366 : 365;
    }
    for (i = 1; i < m; i++) {
        s += mdays[i];
        if (i == 2 && isLeap(y)) {
            s += 1;
        }
    }
    s += d - 1;
    return s;
}

int main(void)
{
    int y1, m1, d1, y2, m2, d2;
    long long diff;

    scanf("%d%d%d", &y1, &m1, &d1);
    scanf("%d%d%d", &y2, &m2, &d2);

    diff = serial(y1, m1, d1) - serial(y2, m2, d2);
    if (diff < 0) {
        diff = -diff;
    }
    printf("%lld\n", diff);
    return 0;
}

