### 题目描述
阅读下面程序，先不运行，推导指定输入下的完整输出。写出关键变量变化、循环或递归的停止条件，并说明一个边界条件为什么不会越界或出错。本题与 R11 共用算法，练习形式为代码分析，不计作独立算法。

```c
#include <stdio.h>

#define MAXN 100005

int h[MAXN];

static void swapElem(int *x, int *y)
{
    int t = *x;
    *x = *y;
    *y = t;
}

/* 三数取中：调整后 h[l] <= h[mid] <= h[r]，再把中位数换到 h[l] 作基准 */
static void medianToLeft(int l, int r)
{
    int mid = l + (r - l) / 2;

    if (h[mid] < h[l]) {
        swapElem(&h[mid], &h[l]);
    }
    if (h[r] < h[l]) {
        swapElem(&h[r], &h[l]);
    }
    if (h[r] < h[mid]) {
        swapElem(&h[r], &h[mid]);
    }
    swapElem(&h[l], &h[mid]);
}

/* 挖坑法分区：返回基准的最终下标，左侧元素都不大于基准，右侧都不小于基准 */
static int partition(int l, int r)
{
    int pivot, i, j;

    medianToLeft(l, r);
    pivot = h[l];
    i = l;
    j = r;
    while (i < j) {
        while (i < j && h[j] > pivot) {
            j--;
        }
        if (i < j) {
            h[i] = h[j];
            i++;
        }
        while (i < j && h[i] < pivot) {
            i++;
        }
        if (i < j) {
            h[j] = h[i];
            j--;
        }
    }
    h[i] = pivot;
    return i;
}

static void quickSort(int l, int r)
{
    int cut;

    if (l >= r) {
        return;
    }
    cut = partition(l, r);
    quickSort(l, cut - 1);
    quickSort(cut + 1, r);
}

int main(void)
{
    int n, k, i;

    scanf("%d%d", &n, &k);
    for (i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    quickSort(0, n - 1);

    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", h[i]);
    }
    printf("\n");
    printf("KTH %d\n", h[k - 1]);
    return 0;
}

```

