    }
    swapElem(&h[l], &h[mid]);
}

/* 挖坑法分区：返回基准的最终下标，左侧元素都不大于基准，右侧都不小于基准 */
static int partition(int l, int r)
{
    int pivot, i, j;

    medianToLeft(l, r);
    pivot = h[l];
    i = l;
    j = r;
    while (i < j) {
        while (i < j && h[j] > pivot) {
            j--;
        }
        if (i < j) {
            h[i] = h[j];
            i++;
        }
        while (i < j && h[i] < pivot) {
            i++;
        }
        if (i < j) {
            h[j] = h[i];
            j--;
        }
    }
    h[i] = pivot;
    return i;
}

static void quickSort(int l, int r)
{
    int cut;

    if (l >= r) {
        return;
    }
    cut = partition(l, r);
    quickSort(l, cut - 1);
    quickSort(cut + 1, r);
}

int main(void)
{
    int n, k, i;

    scanf("%d%d", &n, &k);
    for (i = 0; i < n; i++) {
        scanf("%d", &h[i]);
    }

    quickSort(0, n - 1);

    for (i = 0; i < n; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", h[i]);
    }
    printf("\n");
    printf("KTH %d\n", h[k - 1]);
    return 0;
}

