```c
#include <stdio.h>

#define MAXN 1005
#define MOD 1000000007

static int dp[MAXN][MAXN];
static char blocked[MAXN][MAXN];

int main(void)
{
    int m, n, k, i, j, r, c;

    scanf("%d%d%d", &m, &n, &k);
    for (i = 0; i < k; i++) {
        scanf("%d%d", &r, &c);
        blocked[r][c] = 1;
    }

    if (blocked[1][1]) {
        printf("0\n");
        return 0;
    }
    dp[1][1] = 1;
    for (i = 1; i <= m; i++) {
        for (j = 1; j <= n; j++) {
            if (i == 1 && j == 1) {
                continue;
            }
            if (blocked[i][j]) {
                dp[i][j] = 0;
                continue;
            }
            {
                long long s = 0;
                if (i > 1) {
                    s += dp[i - 1][j];
                }
                if (j > 1) {
                    s += dp[i][j - 1];
                }
                dp[i][j] = (int)(s % MOD);
            }
        }
    }

    printf("%d\n", dp[m][n]);
    return 0;
}

